import urllib.request, concurrent.futures
base='https://raw.githubusercontent.com/NVIDIA/cuda-samples/db3eea23946bca2e90a75eca2b5b3e07158a9e11/'
paths=['Samples/5_Domain_Specific/MonteCarloMultiGPU/MonteCarloMultiGPU.cpp','Samples/5_Domain_Specific/MonteCarloMultiGPU/MonteCarlo_kernel.cu','Samples/5_Domain_Specific/MonteCarloMultiGPU/CMakeLists.txt','Samples/5_Domain_Specific/MonteCarloMultiGPU/realtype.h']
def read(p):
 try:
  s=urllib.request.urlopen(base+p,timeout=20).read().decode()
  lines=s.splitlines()
  ranges={'MonteCarloMultiGPU.cpp':[(45,90),(140,195),(265,330),(420,490)],'MonteCarlo_kernel.cu':[(40,80),(125,180),(185,245)],'CMakeLists.txt':[(1,150)],'realtype.h':[(28,45)]}[p.split('/')[-1]]
  return p+'\\n'+'\\n'.join(f'{i}: {x}' for i,x in enumerate(lines,1) if any(a<=i<=b for a,b in ranges))
 except Exception as e: return p+': '+str(e)
with concurrent.futures.ThreadPoolExecutor() as pool:
 for r in pool.map(read,paths): print(r)
PY"

